function drawMorelullMushroomFairy(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.5;

  const mushSway1 = Math.sin(t * 2.2) * 2.0;
  const mushSway2 = Math.cos(t * 2.2) * 2.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 24 * (1.0 - 0.15 * breathSin), 5, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Chân rễ
  ctx.strokeStyle = '#d9f99d'; ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0,  by + 24); ctx.lineTo(0,  by + 36);
  ctx.moveTo(0,  by + 36); ctx.lineTo(-8, by + 40);
  ctx.moveTo(0,  by + 36); ctx.lineTo(8,  by + 40);
  ctx.stroke();

  // 3. Đầu nấm
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(0, by + 12, 16 * sX, 0, Math.PI * 2); ctx.fill();

  // 4. Má xanh huỳnh quang
  ctx.fillStyle = '#86efac';
  ctx.beginPath(); ctx.arc(-10, by + 14, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(10,  by + 14, 3, 0, Math.PI * 2); ctx.fill();

  // 5. Mắt đen
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.ellipse(-5, by + 12, 2, 4, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(5,  by + 12, 2, 4, 0, 0, Math.PI * 2); ctx.fill();
  }

  // 6. Bèo ren cổ
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(-8, by - 2, 5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0,  by - 4, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(8,  by - 2, 5, 0, Math.PI * 2); ctx.fill();

  // 7. 3 Cây nấm phát quang
  // Chính giữa
  const mx = mushSway1;
  ctx.fillStyle = '#d9f99d';
  ctx.fillRect(mx - 2, by - 24, 4, 22);
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.ellipse(mx, by - 26, 12, 16, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#9333ea';
  ctx.beginPath(); ctx.roundRect(mx - 10, by - 16, 20, 8, 3); ctx.fill();

  // Trái
  const lx = -14 + mushSway2;
  ctx.fillStyle = '#d9f99d';
  ctx.fillRect(lx, by - 16, 3, 16);
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.ellipse(lx - 2, by - 18, 9, 13, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#9333ea';
  ctx.beginPath(); ctx.roundRect(lx - 8, by - 10, 14, 6, 2); ctx.fill();

  // Phải
  const rx = 14 - mushSway2;
  ctx.fillStyle = '#d9f99d';
  ctx.fillRect(rx - 2, by - 14, 3, 14);
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.ellipse(rx + 2, by - 16, 8, 12, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#9333ea';
  ctx.beginPath(); ctx.roundRect(rx - 4, by - 8, 13, 6, 2); ctx.fill();

  ctx.restore();
}
